import React, { useState } from 'react';
import {
  Accordion,
  AccordionDetails,
  AccordionSummary,
  Alert,
  Box,
  Button,
  Card,
  CardContent,
  Chip,
  CircularProgress,
  Stack,
  Tooltip,
  Typography,
} from '@mui/material';
import {
  AutoFixHigh as AutopilotIcon,
  ArrowForward as ArrowIcon,
  ExpandMore as ExpandMoreIcon,
  PlayArrow as PlayArrowIcon,
} from '@mui/icons-material';
import { Link as RouterLink } from 'react-router-dom';
import ApiService from '../../services/api';
import ReportGenerationStepper, { useStagedReportGeneration } from '../reporting/ReportGenerationStepper';
import {
  FRAMEWORK_ACRONYM_HINTS,
  READINESS_ACTION_LABELS,
} from '../../constants/orchestrationUxLabels';
import useReadinessLocale from '../../hooks/useReadinessLocale';

export type PrioritizedReadinessAction = {
  id: string;
  framework: string;
  track: string;
  severity: 'high' | 'medium' | 'low' | string;
  action: string;
  detail?: string | null;
  hubLink?: string | null;
  expectedScoreImpact?: number | null;
  agentSuggested?: boolean;
};

type ComplianceReadinessActionQueueProps = {
  actions: PrioritizedReadinessAction[];
  onRefresh?: () => void;
  period?: string;
  exportApplicable?: boolean;
  layout?: 'default' | 'commandCenter';
  frameworkFilter?: string | null;
  title?: string;
  /** Hub/Disclosure overall score — used to avoid “healthy” empty copy when gaps remain elsewhere. */
  overallReadinessScore?: number | null;
  openGapCount?: number | null;
  /** Parent already owns Check readiness and Auto-fix. Keep only tools that are not on that control. */
  suppressPrimaryActions?: boolean;
};

const severityColor = (severity?: string): 'error' | 'warning' | 'default' => {
  if (severity === 'high') return 'error';
  if (severity === 'medium' || severity === 'med') return 'warning';
  return 'default';
};

const ComplianceReadinessActionQueue: React.FC<ComplianceReadinessActionQueueProps> = ({
  actions,
  onRefresh,
  period = 'annual',
  exportApplicable = false,
  layout = 'default',
  frameworkFilter = null,
  title,
  overallReadinessScore = null,
  openGapCount = null,
  suppressPrimaryActions = false,
}) => {
  const { strings } = useReadinessLocale();
  const [running, setRunning] = useState(false);
  const [orchestrating, setOrchestrating] = useState(false);
  const [generatingAll, setGeneratingAll] = useState(false);
  const stagedGeneration = useStagedReportGeneration({ period, exportApplicable, profile: 'standard' });
  const [emissionsRunning, setEmissionsRunning] = useState(false);
  const [autopilotRunning, setAutopilotRunning] = useState(false);
  const [feedback, setFeedback] = useState<string | null>(null);
  const [error, setError] = useState<string | null>(null);

  const runPrimaryReadinessCheck = async () => {
    setOrchestrating(true);
    setError(null);
    setFeedback(null);
    try {
      const res = await ApiService.orchestrateReportingReadiness({
        period,
        actionLimit: 8,
        runAutopilot: true,
        includeBrsrOrchestration: true,
        includeIsoOrchestration: true,
        includePcfOrchestration: exportApplicable,
        includeCbamOrchestration: exportApplicable,
      });
      const data = (res as {
        data?: {
          message?: string;
          overallReadinessScore?: number;
          overallScoreDelta?: number | null;
          indiaOverallReadinessScore?: number;
          exportOverallReadinessScore?: number;
          exportApplicable?: boolean;
        };
      })?.data;
      const scoreParts = [
        data?.overallReadinessScore != null ? `Overall ${Math.round(data.overallReadinessScore)}%` : null,
        data?.overallScoreDelta != null && data.overallScoreDelta !== 0
          ? `${data.overallScoreDelta > 0 ? '+' : ''}${Math.round(data.overallScoreDelta)}% change`
          : null,
        data?.indiaOverallReadinessScore != null ? `India ${Math.round(data.indiaOverallReadinessScore)}%` : null,
        data?.exportApplicable && data?.exportOverallReadinessScore != null
          ? `Export ${Math.round(data.exportOverallReadinessScore)}%`
          : null,
      ].filter(Boolean);
      setFeedback(
        data?.message?.replace(/orchestration/gi, 'readiness check')
          || (scoreParts.length
            ? `Readiness check complete: ${scoreParts.join(' · ')}.`
            : 'Readiness check complete — review your action list below.')
      );
      onRefresh?.();
    } catch (e) {
      setError(e instanceof Error ? e.message : 'Readiness check failed. Please try again.');
    } finally {
      setOrchestrating(false);
    }
  };

  const runOrchestrateAllReports = async () => {
    setGeneratingAll(true);
    setError(null);
    setFeedback(null);
    try {
      const result = await stagedGeneration.runStandard();
      setFeedback(
        result.bundle?.summary?.message
          || `Generated ${result.bundle?.summary?.successCount ?? 0} reports${
            result.bundle?.summary?.failedCount
              ? ` (${result.bundle.summary.failedCount} failed)`
              : ''
          }.`
      );
      onRefresh?.();
    } catch (e) {
      setError(e instanceof Error ? e.message : 'Full report orchestration failed.');
    } finally {
      setGeneratingAll(false);
    }
  };

  const runEmissionsReporting = async () => {
    setEmissionsRunning(true);
    setError(null);
    setFeedback(null);
    try {
      const frameworks = ['BRSR', 'ISO14064', ...(exportApplicable ? ['CBAM'] : [])];
      const res = await ApiService.orchestrateEmissionsReporting({ period, frameworks });
      const data = (res as { data?: { reporting?: { overallReadinessScore?: number } } })?.data;
      const score = data?.reporting?.overallReadinessScore;
      setFeedback(
        score != null
          ? `Emissions and reporting agents finished — overall readiness ${Math.round(score)}%.`
          : 'Emissions and reporting analysis complete.'
      );
      onRefresh?.();
    } catch (e) {
      setError(e instanceof Error ? e.message : 'Emissions reporting analysis failed.');
    } finally {
      setEmissionsRunning(false);
    }
  };

  const refreshWithAgents = async () => {
    setRunning(true);
    setError(null);
    setFeedback(null);
    try {
      await ApiService.orchestrateReadinessActions({ period, actionLimit: 5 });
      setFeedback('Your action list was updated based on current gaps.');
      onRefresh?.();
    } catch (e) {
      setError(e instanceof Error ? e.message : 'Failed to update the action list');
    } finally {
      setRunning(false);
    }
  };

  const runAutopilot = async () => {
    setAutopilotRunning(true);
    setError(null);
    setFeedback(null);
    try {
      const result = await ApiService.runComplianceHubAutopilot({
        period,
        applyChanges: true,
        runAgents: true,
      });
      const payload = (result as { data?: { closuresApplied?: unknown[]; documentVerifications?: unknown[] } })?.data;
      const closuresApplied = payload?.closuresApplied;
      const documentVerifications = payload?.documentVerifications;
      const closureCount = Array.isArray(closuresApplied) ? closuresApplied.length : 0;
      const docCount = Array.isArray(documentVerifications) ? documentVerifications.length : 0;
      setFeedback(
        closureCount || docCount
          ? `Auto-fix complete — ${docCount} document check(s), ${closureCount} update(s) applied where possible.`
          : 'Auto-fix finished — no additional changes were needed.'
      );
      onRefresh?.();
    } catch (e) {
      setError(e instanceof Error ? e.message : 'Auto-fix from documents failed');
    } finally {
      setAutopilotRunning(false);
    }
  };

  const isCommandCenter = layout === 'commandCenter';
  const filteredActions = frameworkFilter
    ? actions.filter((action) => action.framework === frameworkFilter)
    : actions;
  const queueTitle = title || 'Your action list';

  return (
    <Card variant="outlined" sx={{ mb: 3 }}>
      <CardContent>
        {isCommandCenter ? (
          suppressPrimaryActions ? (
            <Accordion
              disableGutters
              elevation={0}
              sx={{ bgcolor: 'transparent', '&:before': { display: 'none' }, mb: 2 }}
            >
              <AccordionSummary expandIcon={<ExpandMoreIcon />} sx={{ px: 0, minHeight: 40 }}>
                <Typography variant="body2" color="text.secondary">
                  Other report tools
                </Typography>
              </AccordionSummary>
              <AccordionDetails sx={{ px: 0, pt: 0 }}>
                <Stack direction={{ xs: 'column', sm: 'row' }} spacing={1} flexWrap="wrap" useFlexGap>
                  <Button
                    size="small"
                    variant="outlined"
                    disabled={running}
                    onClick={() => void refreshWithAgents()}
                  >
                    {running ? 'Updating…' : strings.updateActionList}
                  </Button>
                  <Button
                    size="small"
                    variant="outlined"
                    disabled={emissionsRunning}
                    onClick={() => void runEmissionsReporting()}
                  >
                    {emissionsRunning ? 'Analyzing…' : READINESS_ACTION_LABELS.analyzeEmissionsForReports}
                  </Button>
                  <Button
                    size="small"
                    variant="outlined"
                    color="secondary"
                    disabled={generatingAll || stagedGeneration.running}
                    onClick={() => void runOrchestrateAllReports()}
                    startIcon={(generatingAll || stagedGeneration.running) ? <CircularProgress size={16} color="inherit" /> : <PlayArrowIcon />}
                  >
                    {(generatingAll || stagedGeneration.running) ? 'Generating all reports…' : READINESS_ACTION_LABELS.orchestrateAllReports}
                  </Button>
                </Stack>
              </AccordionDetails>
            </Accordion>
          ) : (
          <Box sx={{ mb: 3 }}>
            <Typography variant="h6" fontWeight={700} gutterBottom>
              Start here
            </Typography>
            <Typography variant="body2" color="text.secondary" sx={{ mb: 2, maxWidth: 640 }}>
              {strings.checkReadinessSubtitle}
            </Typography>
            <Button
              variant="contained"
              size="large"
              disabled={orchestrating}
              onClick={() => void runPrimaryReadinessCheck()}
              startIcon={orchestrating ? <CircularProgress size={20} color="inherit" /> : <PlayArrowIcon />}
              sx={{ mb: 1 }}
            >
              {orchestrating ? 'Checking readiness…' : strings.checkReadiness}
            </Button>
            <Accordion
              disableGutters
              elevation={0}
              sx={{ bgcolor: 'transparent', '&:before': { display: 'none' }, mt: 1 }}
            >
              <AccordionSummary expandIcon={<ExpandMoreIcon />} sx={{ px: 0, minHeight: 40 }}>
                <Typography variant="body2" color="text.secondary">
                  More options
                </Typography>
              </AccordionSummary>
              <AccordionDetails sx={{ px: 0, pt: 0 }}>
                <Stack direction={{ xs: 'column', sm: 'row' }} spacing={1} flexWrap="wrap" useFlexGap>
                  <Button
                    size="small"
                    variant="outlined"
                    disabled={running}
                    onClick={() => void refreshWithAgents()}
                  >
                    {running ? 'Updating…' : strings.updateActionList}
                  </Button>
                  <Button
                    size="small"
                    variant="outlined"
                    disabled={autopilotRunning}
                    onClick={() => void runAutopilot()}
                    startIcon={autopilotRunning ? <CircularProgress size={16} /> : <AutopilotIcon />}
                  >
                    {autopilotRunning ? 'Applying…' : strings.autoFixFromDocuments}
                  </Button>
                  <Button
                    size="small"
                    variant="outlined"
                    disabled={emissionsRunning}
                    onClick={() => void runEmissionsReporting()}
                  >
                    {emissionsRunning ? 'Analyzing…' : READINESS_ACTION_LABELS.analyzeEmissionsForReports}
                  </Button>
                  <Button
                    size="small"
                    variant="contained"
                    color="secondary"
                    disabled={generatingAll || stagedGeneration.running}
                    onClick={() => void runOrchestrateAllReports()}
                    startIcon={(generatingAll || stagedGeneration.running) ? <CircularProgress size={16} color="inherit" /> : <PlayArrowIcon />}
                  >
                    {(generatingAll || stagedGeneration.running) ? 'Generating all reports…' : READINESS_ACTION_LABELS.orchestrateAllReports}
                  </Button>
                </Stack>
                <Typography variant="caption" color="text.secondary" display="block" sx={{ mt: 1 }}>
                  {READINESS_ACTION_LABELS.updateActionListHint}{' '}
                  {READINESS_ACTION_LABELS.autoFixHint}{' '}
                  {READINESS_ACTION_LABELS.analyzeEmissionsForReportsHint}{' '}
                  {READINESS_ACTION_LABELS.orchestrateAllReportsHint}
                </Typography>
              </AccordionDetails>
            </Accordion>
          </Box>
          )
        ) : (
          <Stack direction="row" justifyContent="space-between" alignItems="flex-start" flexWrap="wrap" gap={1} sx={{ mb: 2 }}>
            <Box>
              <Typography variant="subtitle1" fontWeight={700}>
                Next best actions to raise readiness scores
              </Typography>
              <Typography variant="body2" color="text.secondary">
                Prioritized by gap severity. Use Compliance Hub for the full readiness check workflow.
              </Typography>
            </Box>
            {suppressPrimaryActions ? null : (
            <Stack direction="row" spacing={1} flexWrap="wrap">
              <Button
                size="small"
                variant="contained"
                disabled={orchestrating}
                onClick={() => void runPrimaryReadinessCheck()}
                startIcon={orchestrating ? <CircularProgress size={16} color="inherit" /> : undefined}
              >
                {orchestrating ? 'Checking…' : strings.checkReadiness}
              </Button>
              <Button
                size="small"
                variant="outlined"
                disabled={emissionsRunning}
                onClick={() => void runEmissionsReporting()}
              >
                {emissionsRunning ? 'Analyzing…' : READINESS_ACTION_LABELS.analyzeEmissionsForReports}
              </Button>
              <Button
                size="small"
                variant="contained"
                color="secondary"
                disabled={generatingAll || stagedGeneration.running}
                onClick={() => void runOrchestrateAllReports()}
                startIcon={(generatingAll || stagedGeneration.running) ? <CircularProgress size={16} color="inherit" /> : <PlayArrowIcon />}
              >
                {(generatingAll || stagedGeneration.running) ? 'Generating…' : READINESS_ACTION_LABELS.orchestrateAllReports}
              </Button>
              <Button
                size="small"
                variant="outlined"
                component={RouterLink}
                to="/compliance"
              >
                Open Compliance Hub
              </Button>
            </Stack>
            )}
          </Stack>
        )}

        {feedback ? <Alert severity="success" sx={{ mb: 2 }}>{feedback}</Alert> : null}
        {error ? <Alert severity="error" sx={{ mb: 2 }}>{error}</Alert> : null}
        <ReportGenerationStepper
          running={generatingAll || stagedGeneration.running}
          stages={stagedGeneration.stages}
        />

        <Typography variant="subtitle1" fontWeight={700} sx={{ mb: 1.5 }}>
          {queueTitle}
        </Typography>

        {!filteredActions.length ? (
          <Typography variant="body2" color="text.secondary">
            {frameworkFilter
              ? `No prioritized actions for this framework filter right now. Other modules may still have open gaps — check the gap list and readiness scores for the selected period.`
              : (Number(openGapCount) > 0 || (overallReadinessScore != null && overallReadinessScore < 65))
                ? `No prioritized next actions in this queue, but readiness is not fully healthy yet${
                    overallReadinessScore != null ? ` (${Math.round(overallReadinessScore)}% overall)` : ''
                  }${Number(openGapCount) > 0 ? ` · ${openGapCount} open gap(s) elsewhere` : ''}. Run a readiness check or open module gap details.`
                : `No open gaps detected — your readiness scores look healthy for the current period. Run a readiness check after uploading new bills or receiving a buyer questionnaire.`}
          </Typography>
        ) : (
          <Stack spacing={1.5}>
            {filteredActions.map((action, index) => (
              <Box
                key={action.id}
                sx={{
                  display: 'flex',
                  flexWrap: 'wrap',
                  alignItems: 'flex-start',
                  justifyContent: 'space-between',
                  gap: 1,
                  p: 1.5,
                  borderRadius: 1,
                  bgcolor: 'action.hover',
                }}
              >
                <Box sx={{ flex: 1, minWidth: 220 }}>
                  <Stack direction="row" spacing={1} alignItems="center" flexWrap="wrap" sx={{ mb: 0.5 }}>
                    <Typography variant="body2" fontWeight={700}>
                      {index + 1}. {action.action}
                    </Typography>
                    <Tooltip title={FRAMEWORK_ACRONYM_HINTS[action.framework] || action.framework} arrow>
                      <Chip size="small" label={action.framework} variant="outlined" />
                    </Tooltip>
                    <Chip size="small" label={action.severity} color={severityColor(action.severity)} />
                    {action.agentSuggested ? (
                      <Chip size="small" label="Suggested" color="info" variant="outlined" />
                    ) : null}
                    {action.expectedScoreImpact ? (
                      <Chip size="small" label={`~+${Number(action.expectedScoreImpact).toFixed(1)}%`} color="success" variant="outlined" />
                    ) : null}
                  </Stack>
                  {action.detail ? (
                    <Typography variant="body2" color="text.secondary">
                      {action.detail}
                    </Typography>
                  ) : null}
                </Box>
                {action.hubLink ? (
                  <Button
                    size="small"
                    component={RouterLink}
                    to={action.hubLink}
                    endIcon={<ArrowIcon />}
                  >
                    Open
                  </Button>
                ) : null}
              </Box>
            ))}
          </Stack>
        )}
      </CardContent>
    </Card>
  );
};

export default ComplianceReadinessActionQueue;
